class TaskBinding{static Object value(double r,double i){return new Complex(r,i);}static double[]parts(Object x){return new double[]{((Complex)x).real(),((Complex)x).imaginary()};}static Object operation(Object a,Object b,int op){Complex x=(Complex)a,y=(Complex)b;return switch(op){case 0->x.add(y);case 1->x.subtract(y);case 2->x.multiply(y);default->x.divide(y);};}static Object[]array(Object...a){return java.util.Arrays.copyOf(a,a.length,Complex[].class);}static Object sum(Object[]a){return Complex.sum((Complex[])a);}static Object product(Object[]a){return Complex.product((Complex[])a);}}
